tariff "LTL"
let w = shipment.weight ?? 0 lb
let perCwt = match w {
  ..500 lb => $30/cwt
  500 lb..1_000 lb => $31/cwt
  1_000 lb..2_000 lb => $25/cwt
  _ => $20/cwt
}
charge "Linehaul" = perCwt * w
property "p" {
  vary shipment.weight in 1 lb..5_000 lb
  expect total nondecreasing in shipment.weight
}

tariff "t"
charge "x" = $1/lb * (shipment.weight ?? 0 lb)
property "p" {
  vary shipment.weight in 0.5 lb..2.5 lb
  expect total >= $0
}
